<?php
$kind=$section==='demos'?'demo':'enquiry';
$q=trim(is_string($_GET['q']??null)?$_GET['q']:''); $status=in_array($_GET['status']??'',['New','Viewed','Contacted'],true)?$_GET['status']:'';
$where='kind=?'; $params=[$kind]; if($q!==''){ $where.=' AND (name LIKE ? OR email LIKE ? OR reference LIKE ?)'; array_push($params,'%'.$q.'%','%'.$q.'%','%'.$q.'%'); } if($status){$where.=' AND status=?'; $params[]=$status;}
$count=(int)query('SELECT count(*) FROM enquiries WHERE '.$where,$params)->fetchColumn(); $pages=max(1,(int)ceil($count/15)); $pageNum=min(max(1,(int)($_GET['page']??1)),$pages); $offset=($pageNum-1)*15;
$requests=query('SELECT * FROM enquiries WHERE '.$where.' ORDER BY id DESC LIMIT 15 OFFSET '.$offset,$params)->fetchAll();
?>
<div class="inbox-toolbar"><div class="inbox-tabs"><a class="<?=$status===''?'active':''?>" href="/superadmin/<?=$section?>">All requests</a><a class="<?=$status==='New'?'active':''?>" href="/superadmin/<?=$section?>?status=New">Unread <span data-count="<?=$section?>"><?=$section==='demos'?$unreadDemos:$unreadEnquiries?></span></a></div><a class="button secondary compact" href="/superadmin/export?kind=<?=$kind?>"><?=icon('download')?>Export all CSV</a></div>
<section class="card inbox-card"><form class="table-filters" method="get"><input type="search" name="q" value="<?=e($q)?>" placeholder="Search name, email or reference…" aria-label="Search requests"><select name="status" aria-label="Filter status"><option value="">All statuses</option><?php foreach(['New'=>'Unread','Viewed'=>'Viewed','Contacted'=>'Contacted'] as $value=>$label): ?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=$label?></option><?php endforeach ?></select><button type="submit" class="button secondary compact">Filter</button><span><?=$count?> requests</span></form><div class="inbox-grid inbox-header"><span>Name</span><span>Email</span><span>Received</span><span>Status</span><span></span></div>
<?php foreach($requests as $r): ?><details class="enquiry-row" id="request-<?=$r['id']?>" data-request-id="<?=$r['id']?>" data-status="<?=e($r['status'])?>"><summary class="inbox-grid"><span class="enquiry-name"><i class="unread-dot <?=$r['status']==='New'?'':'viewed-dot'?>"></i><strong><?=e($r['name'])?></strong></span><span class="enquiry-email"><?=e($r['email'])?></span><span class="enquiry-date"><?=e(format_date($r['created_at'],'d M Y'))?><small><?=e(format_date($r['created_at'],'h:i A'))?> IST</small></span><span class="status-cell"><span class="badge <?=strtolower($r['status'])?>"><?=e($r['status']==='New'?'Unread':$r['status'])?></span></span><span class="row-chevron"><?=icon('chevron')?></span></summary><div class="enquiry-details"><div class="request-heading"><div><span class="eyebrow"><?=$kind==='demo'?'DEMO REQUEST':'WEBSITE ENQUIRY'?></span><h3><?=e($r['reference'])?></h3></div><div class="request-actions"><form method="post"><?=csrf()?><input type="hidden" name="action" value="enquiry_status"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="Contacted"><button class="button compact"><?=icon('check')?>Mark as contacted</button></form><form method="post"><?=csrf()?><input type="hidden" name="action" value="enquiry_status"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="New"><button class="button secondary compact">Mark as unread</button></form></div></div><div class="request-detail-grid"><div><span>Contact</span><a href="mailto:<?=e($r['email'])?>"><?=e($r['email'])?></a><a href="tel:<?=e(preg_replace('/[^+0-9]/','',$r['phone']))?>"><?=e($r['phone'])?></a></div><div><span>Preferences</span><strong><?=e($r['program'])?></strong><p><?=e($r['branch'])?></p><p><?=e($r['experience'])?></p></div><?php if($kind==='demo'): ?><div><span>Requested session</span><strong><?=e(format_date($r['preferred_date']))?></strong><p><?=e($r['preferred_time'])?></p><span class="badge draft"><?=e($r['booking_status'])?></span></div><?php endif ?></div><div class="request-message"><span>Message</span><p><?=nl2br(e($r['message']?:'No additional message.'))?></p></div>
<div class="delivery-report"><h4><?=icon('mail')?>Email notification results</h4><?php foreach(json_decode($r['delivery'],true)?:[] as $delivery): ?><div><strong><?=e($delivery['recipient'])?></strong><span class="badge <?=str_starts_with($delivery['status'],'Accepted')?'published':'draft'?>"><?=e($delivery['status'])?></span><p><?=e($delivery['detail'])?></p></div><?php endforeach ?></div>
<form method="post" class="booking-form"><?=csrf()?><input type="hidden" name="action" value="save_booking"><input type="hidden" name="id" value="<?=$r['id']?>"><h4><?=$kind==='demo'?'Booking & outcome':'Follow-up notes'?></h4><div class="booking-fields"><?php if($kind==='demo'): ?><label>Booking status<select name="booking_status"><?php foreach(['Requested','Confirmed','Rescheduled','Attended','No-show','Cancelled'] as $opt): ?><option <?=$r['booking_status']===$opt?'selected':''?>><?=$opt?></option><?php endforeach ?></select></label><label>Scheduled date & time (IST)<input name="scheduled_at" type="datetime-local" value="<?=e($r['scheduled_at'])?>"></label><label>Assigned coach<input name="coach" maxlength="180" value="<?=e($r['coach'])?>"></label><?php else: ?><input type="hidden" name="booking_status" value="<?=e($r['booking_status'])?>"><?php endif ?><label class="wide">Internal notes<textarea name="notes" rows="3" maxlength="6000"><?=e($r['notes'])?></textarea></label></div><div class="booking-bottom"><small>Updates are logged. Contact the applicant separately to confirm arrangements.</small><button class="button secondary compact" type="submit">Save update <?=icon('check')?></button></div></form><p class="consent-record">Consent recorded <?=e(format_date($r['consent_at'],'d M Y, H:i'))?> IST · Enquiries do not activate student accounts.</p><p class="viewed-feedback" role="status"></p></div></details><?php endforeach ?>
<?php if(!$requests): ?><div class="empty-state"><?=icon($kind==='demo'?'calendar':'mail')?><h3><?=$q || $status?'No matching requests.':'Your inbox is ready.'?></h3><p><?=$q || $status?'Try another search or clear the filters.':'Website '.($kind==='demo'?'demo requests':'enquiries').' will appear here, newest first.'?></p></div><?php endif ?></section>
<?php admin_pagination($pageNum,$pages,'/superadmin/'.$section.'?'.http_build_query(['q'=>$q,'status'=>$status]).'&'); ?>
